"""EPD webhook signature verifier — Python, stdlib only.

    header:  EPD-Signature: t=<unix_seconds>,v1=<hex_sha256>
    signed:  HMAC-SHA256(secret, f"{timestamp}.{raw_body}")
    replay:  reject if |now - t| > tolerance_seconds (default 300)
"""

from __future__ import annotations

import hashlib
import hmac
import time
from dataclasses import dataclass
from typing import Union

SIGNATURE_VERSION = "v1"
DEFAULT_TOLERANCE_SECONDS = 300
SIGNING_SECRET_PREFIX = "whsec_"


@dataclass(frozen=True)
class VerifyResult:
    valid: bool
    reason: str | None = None


def verify_webhook(
    payload: Union[str, bytes],
    signature_header: str,
    secret: str,
    tolerance_seconds: int = DEFAULT_TOLERANCE_SECONDS,
) -> VerifyResult:
    """Verify an EPD webhook signature. Test ``.valid``, never the result itself."""
    if not signature_header or not isinstance(signature_header, str):
        return VerifyResult(False, "missing_signature_header")
    if not secret or not isinstance(secret, str):
        return VerifyResult(False, "missing_secret")

    parsed = _parse_signature_header(signature_header)
    if parsed is None:
        return VerifyResult(False, "malformed_signature_header")
    timestamp, signature_hex = parsed

    if abs(int(time.time()) - timestamp) > tolerance_seconds:
        return VerifyResult(False, "timestamp_outside_tolerance")

    payload_bytes = payload.encode("utf-8") if isinstance(payload, str) else payload
    signed_payload = f"{timestamp}.".encode("utf-8") + payload_bytes

    # EPD strips the `whsec_` prefix before HMAC.
    hmac_key = secret[len(SIGNING_SECRET_PREFIX):] if secret.startswith(SIGNING_SECRET_PREFIX) else secret
    expected = hmac.new(hmac_key.encode("utf-8"), signed_payload, hashlib.sha256).hexdigest()

    if not signature_hex:
        return VerifyResult(False, "malformed_signature_hex")

    try:
        expected_b = bytes.fromhex(expected)
        actual_b = bytes.fromhex(signature_hex)
    except ValueError:
        return VerifyResult(False, "malformed_signature_hex")

    if not hmac.compare_digest(expected_b, actual_b):
        return VerifyResult(False, "signature_mismatch")
    return VerifyResult(True)


def _parse_signature_header(header: str) -> tuple[int, str] | None:
    timestamp: int | None = None
    signature: str | None = None
    for part in header.split(","):
        if "=" not in part:
            continue
        k, _, v = part.partition("=")
        k, v = k.strip(), v.strip()
        if k == "t":
            try:
                n = int(v)
                if n > 0:
                    timestamp = n
            except ValueError:
                pass
        elif k == SIGNATURE_VERSION:
            signature = v
    if timestamp is None or signature is None:
        return None
    return timestamp, signature

import json
import logging

from django.conf import settings
from django.http import HttpResponse, HttpResponseBadRequest
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_POST

from .verify import verify_webhook

logger = logging.getLogger(__name__)


@csrf_exempt  # EPD can't send a CSRF token; the HMAC signature is the authentication.
@require_POST
def epd_webhook(request):
    raw = request.body  # raw bytes — never request.POST or re-serialized JSON
    signature = request.headers.get("EPD-Signature", "")

    result = verify_webhook(raw, signature, settings.EPD_WEBHOOK_SECRET)
    if not result.valid:
        logger.warning("rejected EPD webhook: %s", result.reason)
        return HttpResponse(status=401)

    try:
        event = json.loads(raw)
    except ValueError:
        return HttpResponseBadRequest()

    # Deduplicate on event["id"] (EPD retries and replays), persist the event
    # durably, then return 200. Log event id/type only, not the body (PII).
    logger.info("received EPD event %s (%s)", event.get("id"), event.get("type"))

    return HttpResponse(status=200)
